  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "nodemon": "^2.0.22",
    "jest": "^29.5.0",
    "supertest": "^6.3.3"
  },
  "keywords": [
    "express",
    "security",
    "validation"
  ],
  "author": "Security Team",
  "license": "MIT"
}

const request = require('supertest');
const app = require('../app');

describe('POST /users', () => {
  test('should reject requests with missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({})
      .expect(400);

    expect(response.body.error).toBe('Missing required field: name');
  });

  test('should reject requests with non-string name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 })
      .expect(400);

    expect(response.body.error).toBe('Invalid type for name field: expected string');
  });

  test('should reject requests with empty name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' })
      .expect(400);

    expect(response.body.error).toBe('Name field cannot be empty');
  });

  test('should accept valid name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John Doe' })
      .expect(201);

    expect(response.body.name).toBe('John Doe');
    expect(response.body.id).toBeDefined();
    expect(response.body.createdAt).toBeDefined();
  });
});

