  } else {
    console.error(`Health check failed with status code: ${res.statusCode}`);
    process.exit(1);
  }
});

req.on('error', error => {
  console.error('Health check failed:', error.message);
  process.exit(1);
});

req.end();

const app = require('./app');
const http = require('http');

// Test cases
const tests = [
  {
    name: 'Valid name field',
    request: { method: 'POST', path: '/users', data: { name: 'Charlie' } },
    expectedStatus: 201
  },
  {
    name: 'Missing name field',
    request: { method: 'POST', path: '/users', data: { email: 'charlie@example.com' } },
    expectedStatus: 400
  },
  {
    name: 'Non-string name field',
    request: { method: 'POST', path: '/users', data: { name: 123 } },
    expectedStatus: 400
  }
];

let testServer;
let testResults = [];

// Start server on a test port
const startTestServer = () => {
  return app.listen(3001, () => {
    console.log('Test server running on port 3001');
  });
};

// Make HTTP request
const makeRequest = (options, postData) => {
  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve({ statusCode: res.statusCode, data }));
    });

    req.on('error', reject);

    if (postData) {
      req.write(JSON.stringify(postData));
    }

    req.end();
  });
};

// Run a single test
const runTest = async (test) => {
  try {
    const options = {
      hostname: 'localhost',
      port: 3001,
      path: test.request.path,
      method: test.request.method,
      headers: {
        'Content-Type': 'application/json'
      }
    };

    const response = await makeRequest(options, test.request.data);

    const passed = response.statusCode === test.expectedStatus;
    console.log(`${passed ? 'PASS' : 'FAIL'}: ${test.name} (expected ${test.expectedStatus}, got ${response.statusCode})`);

    testResults.push({
      name: test.name,
      passed,
      expected: test.expectedStatus,
      actual: response.statusCode
    });

    return passed;
  } catch (error) {
    console.log(`ERROR: ${test.name} - ${error.message}`);
    testResults.push({
      name: test.name,
      passed: false,
      error: error.message
    });
    return false;
  }
};

// Run all tests
const runAllTests = async () => {
  testServer = startTestServer();

  // Give server a moment to start
  await new Promise(resolve => setTimeout(resolve, 1000));

  console.log('Running validation tests...\n');

  let passedTests = 0;
  for (const test of tests) {
    const passed = await runTest(test);
    if (passed) passedTests++;
  }

  console.log(`\n${passedTests}/${tests.length} tests passed`);

  testServer.close(() => {
    console.log('Test server closed');

    if (passedTests === tests.length) {
      console.log('\n✅ All tests passed! Ready for deployment.');
      process.exit(0);
    } else {
      console.log('\n❌ Some tests failed. Please review before deployment.');
      process.exit(1);
    }
  });
};

